# Build the test grid and connect the red endpoints through each marker center.
g = [[1]*30 for _ in range(30)]
g[1][19] = 2
for r in [6,11,17,22]:
    g[r] = [4]*30
for r,c in [(6,3),(11,22),(17,13),(22,17)]:
    g[r][c:c+3] = [9,9,9]
g[28][12] = 2
out = [row[:] for row in g]
points = [(1,19),(2,19),(2,4),(10,4),(10,24),(16,24),(16,15),(21,15),(21,18),(27,18),(27,12),(28,12)]
for (r1,c1),(r2,c2) in zip(points,points[1:]):
    assert r1==r2 or c1==c2
    for r in range(min(r1,r2),max(r1,r2)+1):
